const fs = require('fs');
const path = require('path');

// Minimal ZIP parser to extract word/document.xml from docx
const buf = fs.readFileSync('/workspace/testbed/docs/customer_report.docx');

// Find End of Central Directory
let eocdOffset = -1;
for (let i = buf.length - 22; i >= 0; i--) {
  if (buf.readUInt32LE(i) === 0x06054b50) { eocdOffset = i; break; }
}
const cdOffset = buf.readUInt32LE(eocdOffset + 16);
const cdEntries = buf.readUInt16LE(eocdOffset + 10);

let offset = cdOffset;
for (let i = 0; i < cdEntries; i++) {
  const sig = buf.readUInt32LE(offset);
  const compMethod = buf.readUInt16LE(offset + 10);
  const compSize = buf.readUInt32LE(offset + 20);
  const uncompSize = buf.readUInt32LE(offset + 24);
  const fnLen = buf.readUInt16LE(offset + 28);
  const extraLen = buf.readUInt16LE(offset + 30);
  const commentLen = buf.readUInt16LE(offset + 32);
  const localHeaderOffset = buf.readUInt32LE(offset + 42);
  const fileName = buf.slice(offset + 46, offset + 46 + fnLen).toString();

  if (fileName === 'word/document.xml') {
    // Read local file header
    const lfnLen = buf.readUInt16LE(localHeaderOffset + 26);
    const lextraLen = buf.readUInt16LE(localHeaderOffset + 28);
    const dataStart = localHeaderOffset + 30 + lfnLen + lextraLen;
    let data;
    if (compMethod === 8) {
      data = require('zlib').inflateRawSync(buf.slice(dataStart, dataStart + compSize));
    } else {
      data = buf.slice(dataStart, dataStart + uncompSize);
    }
    // Strip XML tags, extract text
    let xml = data.toString('utf8');
    // Extract text between <w:t> tags
    const matches = [...xml.matchAll(/<w:t[^>]*>([^<]*)<\/w:t>/g)];
    let currentPara = '';
    let lastEnd = 0;
    // Better: split by paragraph
    const paras = xml.split(/<\/w:p>/);
    for (const para of paras) {
      const texts = [...para.matchAll(/<w:t[^>]*>([^<]*)<\/w:t>/g)];
      if (texts.length > 0) {
        console.log(texts.map(m => m[1]).join(''));
      }
    }
    break;
  }
  offset += 46 + fnLen + extraLen + commentLen;
}
